#ifndef LIST_H
#define LIST_H

/* A singly linked list of ints. */
typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *list_push(Node *head, int value);
int list_length(const Node *head);
int list_sum(const Node *head);
void list_print(const Node *head);
void list_free(Node *head);

#endif

#include <stdio.h>
#include <stdlib.h>
#include "list.h"

Node *list_push(Node *head, int value) {
    Node *n = malloc(sizeof *n);
    if (!n) {
        perror("malloc");
        exit(1);
    }
    n->value = value;
    n->next = head;
    return n;
}

int list_length(const Node *head) {
    int n = 0;
    for (; head; head = head->next) n++;
    return n;
}

int list_sum(const Node *head) {
    int s = 0;
    for (; head; head = head->next) s += head->value;
    return s;
}

void list_print(const Node *head) {
    for (const Node *p = head; p; p = p->next) printf("%d%s", p->value, p->next ? " -> " : "");
    printf("\n");
}

void list_free(Node *head) {
    while (head) {
        Node *next = head->next;
        free(head);
        head = next;
    }
}

#include <stdio.h>
#include "list.h"

int main(void) {
    Node *list = NULL;
    for (int i = 1; i <= 5; i++) list = list_push(list, i * i);
    list_print(list);
    printf("Length: %d, sum: %d\n", list_length(list), list_sum(list));
    list_free(list);
    return 0;
}

/* A tiny test runner: prints TAP ("ok 1 - ...") and fails the build on a wrong answer. */
#include <stdio.h>
#include "list.h"

static int failures = 0, count = 0;

static void check(int ok, const char *name) {
    count++;
    if (!ok) failures++;
    printf("%sok %d - %s\n", ok ? "" : "not ", count, name);
}

int main(void) {
    Node *list = NULL;
    check(list_length(list) == 0, "an empty list has length 0");
    list = list_push(list, 3);
    list = list_push(list, 4);
    check(list_length(list) == 2, "push adds to the list");
    check(list_sum(list) == 7, "sum adds the values");
    check(list->value == 4, "push puts the new value first");
    list_free(list);
    printf("1..%d\n", count);
    return failures ? 1 : 0;
}

