#include <string>

class Account {
public:
    explicit Account(std::string owner);
    const std::string& owner() const { return owner_; }
    long balance() const { return balance_; }
    void deposit(long amount);
    // Returns false (and changes nothing) when there isn't enough money.
    bool withdraw(long amount);

private:
    std::string owner_;
    long balance_ = 0;
};

#include "bank.hpp"

#include <stdexcept>
#include <utility>

Account::Account(std::string owner) : owner_(std::move(owner)) {}

void Account::deposit(long amount) {
    if (amount <= 0) throw std::invalid_argument("deposit must be positive");
    balance_ += amount;
}

bool Account::withdraw(long amount) {
    if (amount <= 0 || amount > balance_) return false;
    balance_ -= amount;
    return true;
}

#include <iostream>

#include "bank.hpp"

int main() {
    Account acc("Aline");
    acc.deposit(5000);
    acc.withdraw(1200);
    std::cout << acc.owner() << " has " << acc.balance() << " RWF" << std::endl;
    return 0;
}

