import gleam/int
import gleam/io
import gleam/list
import gleam/string

// read_line is written in Erlang (src/app_ffi.erl): Gleam's standard library has no stdin.
@external(erlang, "app_ffi", "read_line")
fn read_line() -> String

pub fn main() {
  // Read one line with two whole numbers, e.g. "3 4".
  let numbers =
    read_line()
    |> string.split(" ")
    |> list.filter_map(fn(word) { int.parse(string.trim(word)) })

  case numbers {
    [a, b, ..] -> io.println("Sum: " <> int.to_string(a + b))
    _ -> io.println("Please enter two whole numbers")
  }
}

package main

import (
	"net/http"
	"strings"
	"sync"

	"github.com/gin-gonic/gin"
)

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type store struct {
	mu    sync.Mutex
	todos []Todo
}

func newStore() *store { return &store{todos: []Todo{}} }

func newRouter(s *store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/api/todos", func(c *gin.Context) {
		s.mu.Lock()
		defer s.mu.Unlock()
		c.JSON(http.StatusOK, s.todos)
	})
	r.POST("/api/todos", func(c *gin.Context) {
		var body struct {
			Title string `json:"title"`
		}
		if err := c.ShouldBindJSON(&body); err != nil || strings.TrimSpace(body.Title) == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "title is required"})
			return
		}
		s.mu.Lock()
		defer s.mu.Unlock()
		todo := Todo{ID: len(s.todos) + 1, Title: strings.TrimSpace(body.Title)}
		s.todos = append(s.todos, todo)
		c.JSON(http.StatusCreated, todo)
	})
	return r
}

