/** Turns a mark out of 100 into a letter grade. */
public class Grades {
    public static String letter(int mark) {
        if (mark < 0 || mark > 100) {
            throw new IllegalArgumentException("A mark is between 0 and 100");
        }
        if (mark >= 80) return "A";
        if (mark >= 70) return "B";
        if (mark >= 60) return "C";
        if (mark >= 50) return "D";
        return "F";
    }
}

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;

class GradesTest {
    @Test
    void topMarksAreAnA() {
        assertEquals("A", Grades.letter(92));
    }

    @Test
    void boundariesBelongToTheHigherGrade() {
        assertEquals("B", Grades.letter(70));
        assertEquals("D", Grades.letter(50));
    }

    @Test
    void lowMarksAreAnF() {
        assertEquals("F", Grades.letter(12));
    }

    @Test
    void marksOutsideZeroToHundredAreRefused() {
        assertThrows(IllegalArgumentException.class, () -> Grades.letter(101));
    }
}

public class Main {
    public static void main(String[] args) {
        int[] marks = {92, 70, 55, 12};
        for (int mark : marks) {
            System.out.println(mark + " -> " + Grades.letter(mark));
        }
    }
}

