import { Body, Controller, Get, Param, ParseIntPipe, Post } from "@nestjs/common";
import { TodosService } from "./todos.service";

@Controller("api/todos")
export class TodosController {
  constructor(private readonly todos: TodosService) {}

  @Get()
  all() {
    return this.todos.all();
  }

  @Get(":id")
  one(@Param("id", ParseIntPipe) id: number) {
    return this.todos.one(id);
  }

  @Post()
  create(@Body() body: { title: string }) {
    return this.todos.create(body.title);
  }
}

import { Injectable, NotFoundException } from "@nestjs/common";

export interface Todo {
  id: number;
  title: string;
  done: boolean;
}

@Injectable()
export class TodosService {
  private todos: Todo[] = [{ id: 1, title: "Learn NestJS", done: false }];

  all() {
    return this.todos;
  }

  one(id: number) {
    const t = this.todos.find((x) => x.id === id);
    if (!t) throw new NotFoundException("No such todo");
    return t;
  }

  create(title: string) {
    const t = { id: this.todos.length + 1, title, done: false };
    this.todos.push(t);
    return t;
  }
}

